            B.q("ai-m5-56", "ai-opentelemetry", "Custom spans show up, but the FastAPI server spans for incoming requests are missing. The code creates app = FastAPI() and calls configure_azure_monitor() a few lines later. What is wrong?", listOf("configure_azure_monitor() must run before 'from fastapi import FastAPI', not only before app = FastAPI()", "configure_azure_monitor() must be called in a FastAPI startup event handler, once the app is ready", "opentelemetry-instrumentation-fastapi must be installed, because the distro leaves FastAPI out", "OTEL_SERVICE_NAME must be set, or the server spans are dropped as coming from an unnamed service"), setOf(0), "Requests telemetry from FastAPI is missing when the code imports fastapi.FastAPI before it calls configure_azure_monitor(). Microsoft notes that moving app = FastAPI() below the call is not enough if 'from fastapi import FastAPI' still comes first. Fix it in one of two ways. Write 'import fastapi', call configure_azure_monitor(), then create the app with fastapi.FastAPI(). Or call configure_azure_monitor() first and put 'from fastapi import FastAPI' after it. (Microsoft now recommends the Microsoft OpenTelemetry Distro, package microsoft-opentelemetry with use_microsoft_opentelemetry(), for new Python apps. Apps already on configure_azure_monitor need no change. Don't initialize both distros.)",
                scenario = "Parcelly's tracking API was refactored and its incoming requests disappeared from Application Insights, while custom spans still arrive. The file starts with 'from fastapi import FastAPI' and 'app = FastAPI()', and configure_azure_monitor() is called a few lines later.",
                whyWrong = mapOf(
                    1 to "A startup handler runs after the FastAPI class was imported and the app created, which is already too late for the distro to patch FastAPI.",
                    2 to "The distro bundles the FastAPI instrumentation and turns it on by default.",
                    3 to "The service name labels the role on the map. It does not decide whether server spans are recorded.",
                ),
            ),
            B.q("ai-m5-57", "ai-opentelemetry", "Two custom spans, fetch-notes and rank-notes, must appear nested, with rank-notes as a child of fetch-notes. Which code does that?", listOf("Call tracer.start_span(\"fetch-notes\") and tracer.start_span(\"rank-notes\") one after the other", "Give both spans the same name", "Create the two spans with two different tracers", "with tracer.start_as_current_span(\"fetch-notes\"): and, inside that block, with tracer.start_as_current_span(\"rank-notes\"):"), setOf(3), "start_as_current_span makes the new span the current one for the block, and any span started inside it takes it as its parent. start_span alone creates a span without making it current, so later spans do not nest under it.",
                scenario = "Lumen Health is timing the steps of its workout recommendation request in Python.",
                whyWrong = mapOf(
                    0 to "start_span does not make the span current, so rank-notes is not created as its child.",
                    1 to "Names are labels; they do not create a parent-child link.",
                    2 to "The tracer only names the library that made a span. Nesting comes from the current context.",
                ),
            ),
            B.q("ai-m5-58", "ai-kql", "Which query shows how many different users called the API each day over the last week?", listOf("AppRequests | where TimeGenerated > ago(7d) | summarize dcount(UserId) by bin(TimeGenerated, 1d)", "AppRequests | where TimeGenerated > ago(7d) | summarize count() by bin(TimeGenerated, 1d)", "AppRequests | where TimeGenerated > ago(7d) | distinct UserId", "AppRequests | where TimeGenerated > ago(7d) | summarize max(UserId)"), setOf(0), "dcount returns the number of distinct values, here users, per day. It is an estimate with a small error, which is the usual trade-off for speed on large tables.",
                scenario = "Rydo's product team wants daily active users of the backend, as seen from its requests.",
                whyWrong = mapOf(
                    1 to "count() counts requests, so a busy user is counted many times.",
                    2 to "distinct lists the users for the whole week, with no per-day number.",
                    3 to "max returns one id, the largest in text order, not a count.",
                ),
            ),
            B.q("ai-m5-59", "ai-kql", "The API sets a span attribute quiz.topic on every request. Which query shows the average duration per topic?", listOf("AppRequests | extend topic = tostring(customDimensions[\"quiz.topic\"]) | summarize avg(DurationMs) by topic", "AppRequests | extend topic = tostring(Properties[\"quiz.topic\"]) | summarize avg(DurationMs) by topic", "AppTraces | extend topic = tostring(Properties[\"quiz.topic\"]) | summarize avg(DurationMs) by topic", "AppRequests | extend topic = tostring(Properties.quiz.topic) | summarize avg(DurationMs) by topic"), setOf(1), "Custom attributes are stored in the Properties column (customDimensions in the classic view), a dynamic bag of values. You read one with Properties[\"name\"] and convert it with tostring before grouping by it.",
                scenario = "Quizly suspects that questions on some topics are much slower to answer than others.",
                whyWrong = mapOf(
                    0 to "customDimensions is the column name in the classic requests table. In the workspace AppRequests table the bag is called Properties.",
                    2 to "AppTraces holds log lines, which have no request duration.",
                    3 to "Dot notation reads a key named quiz and then a key named topic inside it. A key that contains a dot must be read with brackets, so every row gets an empty topic.",
                ),
            ),
            B.q("ai-m5-60", "ai-kql", "From the Application Insights Logs page, you need requests joined with container console lines that live in a separate Log Analytics workspace. How do you reach the other table?", listOf("Copy the console lines into Application Insights first", "Use workspace(\"tt-logs\").ContainerAppConsoleLogs_CL inside the query", "Run two queries and compare them by eye", "Use the union operator with no source"), setOf(1), "A cross-resource query names another workspace with workspace() (or another Application Insights resource with app()), so one query can join tables from both, as long as you can read both.",
                scenario = "Brightdesk's API telemetry goes to Application Insights, while its Container Apps environment writes console logs to a separate workspace called tt-logs.",
